import React, { useEffect, useMemo, useState } from 'react';
import { adminAPI } from '../../services/api';
import { useAuth } from '../../contexts/AuthContext';

const Reviews = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [reviews, setReviews] = useState([]);
  const [pagination, setPagination] = useState({ currentPage: 1, totalPages: 1, totalItems: 0, pageSize: 10 });
  const [filters, setFilters] = useState({ minRating: '', maxRating: '', courseId: '', studentId: '', sortBy: 'createdAt', sortOrder: 'desc' });

  const canAccess = user?.role === 'admin';

  const load = async (page = 1) => {
    try {
      setLoading(true);
      const params = { page, limit: pagination.pageSize, ...filters };
      const res = await adminAPI.getAllReviews(params);
      setReviews(res.data?.data?.reviews || []);
      setPagination(res.data?.data?.pagination || { currentPage: 1, totalPages: 1, totalItems: 0, pageSize: 10 });
    } catch (e) {
      setError(e.response?.data?.message || 'Erreur de chargement');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (canAccess) load(1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canAccess]);

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters((prev) => ({ ...prev, [name]: value }));
  };

  const applyFilters = () => load(1);
  const clearFilters = () => { setFilters({ minRating: '', maxRating: '', courseId: '', studentId: '', sortBy: 'createdAt', sortOrder: 'desc' }); load(1); };

  if (!canAccess) return <div className="container"><div className="card" style={{ padding: '1rem' }}>Accès refusé.</div></div>;

  return (
    <div className="container" style={{ maxWidth: 1200, margin: '0 auto', padding: '1rem' }}>
      <h2 style={{ marginBottom: '1rem' }}>Avis et Évaluations (Admin)</h2>
      <div className="card" style={{ marginBottom: '1rem' }}>
        <div className="card-body" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: '0.75rem' }}>
          <input name="minRating" value={filters.minRating} onChange={handleFilterChange} placeholder="Note min (1-5)" />
          <input name="maxRating" value={filters.maxRating} onChange={handleFilterChange} placeholder="Note max (1-5)" />
          <input name="courseId" value={filters.courseId} onChange={handleFilterChange} placeholder="ID cours" />
          <input name="studentId" value={filters.studentId} onChange={handleFilterChange} placeholder="ID étudiant" />
          <select name="sortBy" value={filters.sortBy} onChange={handleFilterChange}>
            <option value="createdAt">Date</option>
            <option value="rating">Note</option>
            <option value="helpfulVotes">Votes utiles</option>
          </select>
          <select name="sortOrder" value={filters.sortOrder} onChange={handleFilterChange}>
            <option value="desc">Desc</option>
            <option value="asc">Asc</option>
          </select>
          <div style={{ display: 'flex', gap: '0.5rem' }}>
            <button className="btn btn-primary" onClick={applyFilters}>Appliquer</button>
            <button className="btn" onClick={clearFilters}>Réinitialiser</button>
          </div>
        </div>
      </div>

      {loading && <div className="card" style={{ padding: '1rem' }}>Chargement...</div>}
      {error && <div className="card" style={{ padding: '1rem', color: 'var(--danger)' }}>{error}</div>}

      {!loading && (
        <div className="card">
          <div className="card-body" style={{ overflowX: 'auto' }}>
            <table className="table" style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead>
                <tr>
                  <th style={{ textAlign: 'left' }}>Cours</th>
                  <th style={{ textAlign: 'left' }}>Étudiant</th>
                  <th>Note</th>
                  <th style={{ textAlign: 'left' }}>Commentaire</th>
                  <th>Votes utiles</th>
                  <th>Date</th>
                </tr>
              </thead>
              <tbody>
                {reviews.map((r) => (
                  <tr key={r._id}>
                    <td>{r.course?.title}</td>
                    <td>{r.student?.firstName} {r.student?.lastName}</td>
                    <td style={{ textAlign: 'center' }}>⭐ {r.rating}</td>
                    <td>{r.comment || '-'}</td>
                    <td style={{ textAlign: 'center' }}>{r.helpfulVotes || 0}</td>
                    <td style={{ textAlign: 'center' }}>{new Date(r.createdAt).toLocaleDateString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.75rem' }}>
              <div>Page {pagination.currentPage} / {pagination.totalPages} • {pagination.totalItems} avis</div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button className="btn" disabled={pagination.currentPage <= 1} onClick={() => load(pagination.currentPage - 1)}>Précédent</button>
                <button className="btn" disabled={pagination.currentPage >= pagination.totalPages} onClick={() => load(pagination.currentPage + 1)}>Suivant</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Reviews;
